INSERT INTO public.recipes (
  title, slug, description, image_url, source_url, category, cuisine,
  servings, prep_time_minutes, cook_time_minutes, difficulty, instructions,
  calories_per_serving, protein_g_per_serving, fat_g_per_serving, carbs_g_per_serving, fiber_g_per_serving, sodium_mg_per_serving,
  total_calories, total_protein_g, total_fat_g, total_carbs_g, total_fiber_g, total_sodium_mg, is_verified
) VALUES
  ('đuôi heo hầm hạt sen táo đỏ thơm ngon bổ dưỡng', 'cach-nau-duoi-heo-ham-hat-sen-tao-do-thom-ngon-bo-duong', 'Trong y học và ẩm thực phương Đông, đuôi heo được xem là một kho tàng chất dinh dưỡng, mang lại những lợi ích sức khỏe đáng kể, là nguyên liệu góp mặt trong nhiều món ăn ngon bổ. Đuôi heo khá dễ chế biến, từ đuôi heo có thể tạo ra nhiều món ăn [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/JQV-o5DxsDY-HD.jpg', 'https://bepxua.vn/cach-nau-duoi-heo-ham-hat-sen-tao-do-thom-ngon-bo-duong/', 'mon_man', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Bào vỏ các củ. Cho vào thau nước 1 muỗng canh muối khuấy tan rồi cho cà rốt, củ sen, nấm đông cô đã bỏ cùi, hành ngò đã lặt vào ngâm rửa sạch, xả lại nước. Củ sen, cà rốt xắt miếng. Tỉa nấm nếu thích. Tỏi, hành tím cho vào máy xay gia vị xay nát."},{"step_number":2,"title":"Bước 2","description":"Cho vào thau 1 muỗng canh muối và đuôi heo rồi bóp cạo đuôi heo và rửa sạch lại."},{"step_number":3,"title":"Bước 3","description":"Cho vào nồi 1l nước lọc, 1 muỗng canh nước mắm khuấy đều rồi cho đuôi heo vào trụng 4-5 phút sau đó vớt ra rửa sạch từng cục."},{"step_number":4,"title":"Bước 4","description":"Cho vào tô đuôi heo, ½ muỗng canh hạt nêm, 1 muỗng canh đường phèn, ½ muỗng cafe bột ngọt, ½ muỗng cafe muối, 2 muỗng canh nước tương, ½ hành tỏi xay, tiêu xay rồi trộn đều."},{"step_number":5,"title":"Bước 5","description":"Cho 1 muỗng canh dầu ăn vào nồi khác đun nóng, dầu nóng cho phần hành tỏi xay còn lại vào phi thơm rồi cho đuôi heo vào xào đều 1-2 phút."},{"step_number":6,"title":"Bước 6","description":"Cho 2,5l nước lọc vào nồi, nấu sôi 2-3 phút rồi vớt bọt, hầm đuôi heo 20 phút."},{"step_number":7,"title":"Bước 7","description":"Cho hạt sen, cà rốt, củ sen vào nồi hầm tiếp 15-20 phút thì cho táo đỏ và nấm đông cô vào nấu thêm 5 phút. Nêm 1 muỗng canh hạt nêm, ½ muỗng canh muối vào khuấy đều và thêm gốc hành lá, tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Múc đuôi heo hầm hạt sen táo đỏ ra tô, thêm hành lá tiêu xay tùy thích và thưởng thức."}]'::jsonb, 142.1, 7.9, 0.4, 26.7, 2, 15021.4, 568.6, 31.5, 1.6, 106.7, 8.1, 60085.5, true),
  ('Muối Tôm Khô Campuchia Tại Nhà – Ăn Là Ghiền, Chấm Gì Cũng Cuốn', 'cach-lam-muoi-tom-kho-campuchia-tai-nha-an-la-ghien-cham-gi-cung-cuon', 'Hôm nay mình muốn chia sẻ với cả nhà công thức làm muối tôm khô Campuchia mà mình hay làm ở nhà mỗi khi thèm ăn vặt hay đổi món cho bữa cơm gia đình. Món này thơm mùi tôm khô với ruốc rang, vị mặn ngọt cay hài hòa, ăn với cơm nóng cũng [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/08/muoi-tom-kho-campuchia2.jpg', 'https://bepxua.vn/cach-lam-muoi-tom-kho-campuchia-tai-nha-an-la-ghien-cham-gi-cung-cuon/', 'mon_man', 'vietnamese', 4, 15, 30, 'easy', '[{"step_number":1,"title":"Bước 1: Sơ chế tôm khô","description":"Tôm khô đem ngâm nước nóng khoảng 30 phút cho mềm ra, sau đó vớt ra để thật ráo nước. Bước này quan trọng lắm nha, tôm mềm thì giã mới nhuyễn và dẻo được."},{"step_number":2,"title":"Bước 2: Rang ruốc khô","description":"Bắc chảo lên rang ruốc khô cho thơm, rang thêm khoảng 1 phút cho ruốc dậy mùi rồi cho ra thau hoặc cối."},{"step_number":3,"title":"Bước 3: Giã muối, tỏi, ớt","description":"Cho muối hột, muối hầm, bột ngọt, ớt, tỏi vào giã cho thật nhuyễn. Sau đó cho tôm khô đã ráo nước vào giã sơ chung, không cần giã quá nhuyễn để còn cảm nhận được xác tôm."},{"step_number":4,"title":"Bước 4: Rang muối tôm","description":"Cho hỗn hợp vừa giã cùng với đường thốt nốt vào chảo, rang lửa nhỏ liu riu, đảo đều tay đến khi hỗn hợp keo sệt lại là được. Nhớ để lửa nhỏ thôi để muối không bị khét mà lại lên màu đẹp."},{"step_number":5,"title":"Bước 5: Để nguội và thưởng thức","description":"Tắt bếp, để muối tôm nguội hẳn thì hỗn hợp sẽ kẹo dẻo lại, đúng chuẩn muối tôm Campuchia ăn là ghiền. Cho vào hũ thủy tinh sạch, đậy kín để bảo quản ăn dần được lâu."}]'::jsonb, 243.7, 16.9, 0.9, 42, 0.4, 12378.6, 974.7, 67.7, 3.6, 167.8, 1.8, 49514.5, true),
  ('Lẩu Thái Siêu Ngon Tại Nhà – Chua Cay Đậm Đà, Ai Ăn Cũng Ghiền', 'cach-nau-lau-thai-sieu-ngon-tai-nha-chua-cay-dam-da-ai-an-cung-ghien', 'Nồi lẩu này đủ cho khoảng 3-4 người ăn no nê, chị em cứ yên tâm chuẩn bị theo định lượng bên dưới nhé.', 'https://bepxua.vn/wp-content/uploads/2026/08/757A3895.jpg', 'https://bepxua.vn/cach-nau-lau-thai-sieu-ngon-tai-nha-chua-cay-dam-da-ai-an-cung-ghien/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1: Phi thơm nguyên liệu tạo màu và mùi","description":"Bắc nồi lên bếp, cho 2 muỗng canh dầu điều vào đun nóng. Cho thơm, cà chua, sả, riềng vào đảo đều cho dậy mùi thơm."},{"step_number":2,"title":"Bước 2: Nêm gia vị tạo vị chua cay đặc trưng","description":"Cho vào nồi 10 muỗng canh tương cà, 8 muỗng canh tương ớt, 5 muỗng canh đường phèn. Xào đều trong 2-3 phút, thích ăn cay thì cho thêm ớt tươi tùy khẩu vị."},{"step_number":3,"title":"Bước 3: Nấu nước lẩu","description":"Đổ vào nồi 2,5 lít nước lọc cùng 4-5 lá chanh đã vò sơ. Nấu cho sôi, nhớ vớt bọt để nước lẩu được trong. Sau đó hạ lửa, nấu tiếp 10-15 phút cho sả, riềng ra hết mùi thơm."},{"step_number":4,"title":"Bước 4: Lọc lấy nước lẩu","description":"Vớt bỏ hết phần xác (sả, riềng, thơm, cà chua) ra khỏi nồi, chỉ giữ lại phần nước lẩu trong veo, thơm phức."},{"step_number":5,"title":"Bước 5: Nêm nếm cho vừa vị","description":"Cho vào nồi 3 muỗng canh hạt nêm, 5 muỗng canh nước mắm, 10 muỗng canh nước cốt me, 1 muỗng canh bột ngọt. Khuấy đều rồi nếm lại, canh sao cho nước lẩu có vị chua cay mặn ngọt hài hòa, đậm đà là được (vì lát nữa ăn kèm topping và rau nữa nên đừng nêm quá nhạt)."},{"step_number":6,"title":"Bước 7: Thưởng thức","description":"Nhúng rau ăn lẩu khoảng 30 giây là chín tới, giòn ngọt. Thịt bò thì chỉ cần nhúng 15 giây là mềm, không bị dai. Gắp rau và topping ra ăn cùng bún tươi, chấm với nước mắm sả ớt tỏi phi là ngon hết sẩy!"}]'::jsonb, 453.7, 58.8, 6.5, 40, 2.5, 6514.7, 1814.7, 235.3, 25.9, 159.8, 9.9, 26058.8, true),
  ('Cá Biển Kho Cà Chua – Món Kho Đưa Cơm Cả Nhà Ai Cũng Mê', 'ca-bien-kho-ca-chua-mon-kho-dua-com-ca-nha-ai-cung-me', 'Bếp chia sẻ công thức cá biển kho cà chua đậm đà, thịt cá mềm ngọt, nước kho sánh thơm, chan cơm hết sạch nồi – làm một lần là ghiền!', 'https://bepxua.vn/wp-content/uploads/2026/08/cabienkhocachua.jpg', 'https://bepxua.vn/ca-bien-kho-ca-chua-mon-kho-dua-com-ca-nha-ai-cung-me/', 'mon_an_sang', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1: Sơ chế nguyên liệu","description":"Cá làm sạch, cắt khúc vừa ăn. Tỏi và hành tím băm nhuyễn (hoặc xay nhuyễn cho nhanh). Cà chua xắt múi cau, hành lá xắt nhỏ, ớt sừng xắt lát, ớt cay đập dập. Các bạn nên chuẩn bị sẵn hết ra chén cho tiện thao tác nhé."},{"step_number":2,"title":"Bước 2: Thắng đường tạo màu","description":"Bắc nồi lên bếp, cho mỡ heo và 1,5 muỗng canh đường vào, nấu tan cho đến khi đường chuyển màu cánh gián. Đây là bí quyết giúp nồi cá kho lên màu đẹp tự nhiên mà không cần nước màu công nghiệp."},{"step_number":3,"title":"Bước 3: Phi thơm hành tỏi, áp chảo cá","description":"Cho hành tỏi băm vào phi thơm, sau đó cho cá vào, lật đều tay cho cá săn lại hai mặt. Bước này giúp cá không bị nát khi kho lâu."},{"step_number":4,"title":"Bước 4: Nêm nếm và kho sơ","description":"Nêm vào nồi: 1 muỗng canh đường, 1/2 muỗng cà phê muối, 1 muỗng cà phê bột ngọt, 4 muỗng canh nước mắm. Kho lửa nhỏ khoảng 2-3 phút cho cá thấm đều gia vị."},{"step_number":5,"title":"Bước 5: Cho nước, cà chua, ớt vào kho","description":"Đổ 500ml nước nóng vào nồi, cho cà chua và ớt vào. Kho lửa nhỏ liu riu 30-40 phút cho đến khi cà chua nhừ, cá mềm và thấm vị đậm đà. Trong lúc kho, các bạn nhớ thỉnh thoảng vớt bọt và trở cá nhẹ tay để cá chín đều mà không bị vỡ."},{"step_number":6,"title":"Bước 6: Hoàn thành","description":"Khi nước kho sánh lại, cá mềm thơm, rắc hành lá xắt nhỏ vào, đảo nhẹ rồi tắt bếp. Vậy là xong nồi cá biển kho cà chua thơm phức, sẵn sàng lên mâm!"}]'::jsonb, 120, 2, 7, 12.2, 0.9, 4369.4, 479.9, 7.9, 28, 48.7, 3.5, 17477.6, true),
  ('trứng kho quẹt béo ngon ăn là ghiền', 'cach-lam-trung-kho-quet-beo-ngon-an-la-ghien', 'Kho quẹt là món ăn dân dã thân thương đặc trưng của người Nam Bộ. Món ăn này có cách chế biến đơn giản từ những nguyên liệu gần gũi trong căn bếp mỗi nhà như tóp mỡ, tôm khô, hành ớt… Kho quẹt được gọi vui là món “nhà nghèo” vì tiết kiệm, một [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/10/imshYdnU6QE-HD.jpg', 'https://bepxua.vn/cach-lam-trung-kho-quet-beo-ngon-an-la-ghien/', 'mon_kho', 'vietnamese', 4, 20, 45, 'easy', '[{"step_number":1,"title":"Bước 1","description":"Cho 2 muỗng canh mỡ heo vào chảo đun nóng, mỡ nóng cho 1 phần hành tím, gốc hành lá xắt lát vào phi thơm rồi cho nước mắm và đường vào nấu tan đường."},{"step_number":2,"title":"Bước 2","description":"Cho tiếp 1 muỗng canh tương ớt, ½ muỗng cafe bột ngọt vào nấu sôi lại rồi cho tôm khô đã ngâm mềm vào kho lửa vừa khoảng 2-3 phút."},{"step_number":3,"title":"Bước 3","description":"Sốt sôi đập trứng cho vào chảo kho lửa nhỏ, canh độ chín của trứng theo ý thích rồi cho 1 muỗng canh tóp mỡ, phần hành tím, gốc hành lá còn lại, hành lá- ớt xắt nhỏ, tiêu xay vào và tắt bếp."},{"step_number":4,"title":"Bước 4","description":"Chấm kho quẹt với rau củ hoặc ăn với cơm nóng và thưởng thức."}]'::jsonb, 198, 13.4, 8.9, 16.1, 0.2, 2931.8, 791.8, 53.5, 35.6, 64.3, 0.8, 11727.2, true),
  ('mì xào hải sản siêu ngon khó cưỡng', 'cach-lam-mi-xao-hai-san-sieu-ngon-kho-cuong', 'Nếu bạn đang muốn đổi gió bởi những món ăn quen thuộc hàng ngày, hãy thử ngay món mì xào nhé. Mì xào là món ăn phổ biến trong ẩm thực châu Á cũng như ẩm thực Việt. Sự đa dạng trong cách chế biến và nguyên liệu tạo ra nhiều phiên bản mì xào [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/10/maxresdefault.jpg', 'https://bepxua.vn/cach-lam-mi-xao-hai-san-sieu-ngon-kho-cuong/', 'mon_an_sang', 'vietnamese', 4, 15, 20, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Mì đem ngâm nước 12-15 phút rồi vớt mì ra để ráo. Tôm mực làm rửa sạch; mực xắt miếng vừa ăn; tôm lột vỏ, bỏ chỉ lưng, xẻ sâu ⅔."},{"step_number":2,"title":"Bước 2","description":"Cho tôm mực vào thau, thêm 1 muỗng cafe muối rồi chế nước sôi vào trụng 30s sau đó vớt tôm mực ra đem ngâm đá 10 phút cho tôm, mực săn giòn. Tôm mực sau khi ngâm thì vớt ra để ráo."},{"step_number":3,"title":"Bước 3","description":"Rau củ làm rửa sạch. Cải thảo, cà rốt xắt miếng vừa không quá dày. Nấu sôi 1l nước rồi cho gốc cải thảo, cà rốt vào luộc 1 phút, vớt ra. Tỏi cho vào máy xay gia vị xay nhuyễn."},{"step_number":4,"title":"Bước 4","description":"Cho vào chén ½ muỗng canh hạt nêm, 2 muỗng canh nước tương, ½ muỗng canh hắc xì dầu, 2 muỗng canh dầu hào, 1 muỗng canh tương ớt, 1 muỗng canh tương cà, 1 muỗng canh đường, ½ muỗng cafe tiêu xay rồi khuấy đều làm sốt xào."},{"step_number":5,"title":"Bước 5","description":"Cho 1 muỗng canh dầu ăn vào chảo đun nóng, dầu nóng cho ½ phần tỏi xay vào phi thơm rồi cho cá viên vào chiên 2 phút sau đó cho tôm mực vào, rưới 2 muỗng canh sốt xào xào đều 1 phút rồi cho ra dĩa."},{"step_number":6,"title":"Bước 6","description":"Rửa sạch chảo, cho 3 muỗng canh dầu ăn vào chảo đun nóng, dầu nóng cho hết phần tỏi xay còn lại vào phi thơm rồi cho lá cải thảo vào xào sau đó cho gốc cải thảo và cà rốt vào, rưới 2 muỗng canh sốt xào xào đều."},{"step_number":7,"title":"Bước 7","description":"Cho mì vào chảo rau củ, rưới hết sốt xào vào xốc đều rồi cho tiếp hải sản đã xào vào xốc đều. Thêm hành lá, ngò rí, ớt xắt nhỏ và rưới 1 muỗng cafe dầu mè vào xốc đều và tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Cho mì xào hải sản ra dĩa, thêm tiêu xay tùy ý và thưởng thức."}]'::jsonb, 416.9, 37.6, 7.1, 50.5, 4.7, 5420, 1667.5, 150.3, 28.3, 201.9, 18.7, 21680.1, true),
  ('Cá Chốt Kho Tiêu Đậm Đà, Thơm Ngon Như Ngoài Hàng', 'cach-kho-ca-chot-kho-tieu-dam-da-thom-ngon-nhu-ngoai-hang', 'Nhà mình hay nấu món này vào những hôm trời se lạnh hoặc đơn giản là muốn đổi vị cho mâm cơm gia đình. Cá chốt kho tiêu tuy dân dã nhưng lại "đưa cơm" cực kỳ – thịt cá chắc, ngọt tự nhiên, quyện với vị mặn mà của nước mắm, cay nồng của tiêu xanh và ớt, ăn hoài không ngán. Hôm nay mình chia sẻ công t', 'https://bepxua.vn/wp-content/uploads/2026/09/Snapshot_20260902163134.jpg', 'https://bepxua.vn/cach-kho-ca-chot-kho-tieu-dam-da-thom-ngon-nhu-ngoai-hang/', 'mon_kho', 'vietnamese', 4, 20, 45, 'medium', '[{"step_number":1,"title":"Bước 1 – Làm hành ớt: ","description":"Hành tím và ớt đem xay hoặc băm cho thật nhuyễn."},{"step_number":2,"title":"Bước 2 – Phi thơm: ","description":"Bắc chảo lên bếp, cho 2 muỗng canh mỡ heo vào, đợi nóng rồi cho hành ớt vào phi cho dậy mùi thơm."},{"step_number":3,"title":"Bước 3 – Ướp và nêm cá: ","description":"Cho cá chốt vào chảo, nêm 1 muỗng canh đường, 1/2 muỗng cà phê bột ngọt, 5 muỗng canh nước mắm, đảo nhẹ tay cho cá thấm đều gia vị."},{"step_number":4,"title":"Bước 4 – Lên màu và kho lửa vừa: ","description":"Thêm 2 muỗng canh nước màu thốt nốt vào, kho ở lửa vừa khoảng 3-5 phút cho cá săn lại và lên màu đẹp."},{"step_number":5,"title":"Bước 5 – Kho thêm cho thấm: ","description":"Chan 150ml nước nóng vào, kho thêm 5-7 phút nữa để cá chín đều và ngấm gia vị từ trong ra ngoài."},{"step_number":6,"title":"Bước 6 – Thêm tiêu xanh: ","description":"Trong lúc chờ, xắt nhỏ hành lá, ớt, tiêu xanh đập dập cắt khúc. Cho tiêu xanh vào nồi cá để dậy mùi thơm đặc trưng."},{"step_number":7,"title":"Bước 7 – Hoàn thiện: ","description":"Thêm 1 muỗng canh mỡ heo để nước kho bóng đẹp, sau đó rắc hành lá, ớt, tiêu xay lên trên là hoàn thành."}]'::jsonb, 204.3, 21.3, 7.9, 12.2, 0.2, 243, 817, 85.2, 31.5, 48.8, 0.8, 971.9, true),
  ('Miến Mềm Tơi Ngon, Đảm Bảo Không Dính', 'cach-xao-mien-mem-toi-ngon-dam-bao-khong-dinh', 'Mấy chị em nội trợ chắc không lạ gì cảnh xào miến xong mà sợi miến cứ dính chùm lại với nhau, ăn không ngon. Hôm nay mình chia sẻ cách xào miến gà rau củ mềm tơi từng sợi, không hề bết dính, mà vị lại đậm đà thơm ngon. Công thức này nhà [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2026/09/cach-xao-mien-mem-toi-dai-ngon-dam-bao-ko-dinh.mp4_snapshot_00.06.745.jpg', 'https://bepxua.vn/cach-xao-mien-mem-toi-ngon-dam-bao-khong-dinh/', 'mon_an_sang', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1: Sơ chế miến","description":"Miến dong ngâm với nước lạnh khoảng 30 phút cho mềm, sau đó rửa lại và để ráo, cắt khúc vừa ăn. Đây là bước quan trọng nhất quyết định miến có tơi mềm hay không, chị em nhớ ngâm đủ thời gian, đừng ngâm nước nóng vì miến sẽ nhão và dễ dính cục khi xào."},{"step_number":2,"title":"Bước 2: Sơ chế rau củ và thịt gà","description":"Cải thìa bỏ bớt lá, chẻ cọng to cho nhanh chín đều. Cà rốt bào sợi, nấm mèo ngâm mềm rồi xắt sợi. Đùi gà lóc lấy thịt, rửa sạch, xắt miếng vừa ăn. Hành tím xắt lát, hành lá và ngò rí xắt khúc để riêng."},{"step_number":3,"title":"Bước 3: Trộn miến với gia vị","description":"Cho cải thìa, cà rốt, nấm mèo và miến dong vào chung một tô lớn. Nêm vào 1/2 muỗng canh hạt nêm, 1/2 muỗng canh đường, 2 muỗng canh nước tương, 2 muỗng canh dầu hào rồi trộn đều cho miến và rau củ thấm gia vị."},{"step_number":4,"title":"Bước 4: Phi hành, xào gà","description":"Bắc chảo với 5 muỗng canh mỡ heo, cho hành tím vào phi thơm vàng, vớt ra để riêng làm hành phi rắc lên món ăn sau này. Múc bớt mỡ ra chỉ chừa lại khoảng 2 muỗng canh trong chảo, cho thịt gà vào xào săn."},{"step_number":5,"title":"Bước 5: Nêm nếm thịt gà","description":"Thêm vào 2 muỗng canh nước tương, 1 muỗng canh dầu hào, 1/2 muỗng cà phê tiêu xay, đảo đều khoảng 5 phút cho thịt gà thấm vị. Nếu thấy gà xào ra ít nước thì cho thêm khoảng 100ml nước vào để chảo có đủ độ ẩm cho bước xào miến sau."},{"step_number":6,"title":"Bước 6: Cho miến vào xào","description":"Đổ phần miến và rau củ đã trộn gia vị vào chảo, xốc đều tay khoảng 5 phút cho miến chín và mềm tơi ra từng sợi, không bị vón cục. Khi thấy sợi miến trong, mềm là đã đạt."},{"step_number":7,"title":"Bước 7: Hoàn thành","description":"Cho giá đỗ, hành lá, ngò rí vào, xốc đều thêm 1 phút rồi tắt bếp. Múc miến ra đĩa, rắc thêm hành phi lên trên là có ngay món miến xào thơm ngon, hấp dẫn."}]'::jsonb, 805.7, 32.9, 43.3, 70.8, 4, 1783.4, 3223, 131.7, 173.4, 283.3, 16, 7133.6, true),
  ('lẩu riêu tôm siêu ngon bất bại', 'cach-nau-lau-rieu-tom-sieu-ngon-bat-bai', 'Nếu như riêu cua là nguyên liệu quá đỗi quen thuộc trong ẩm thực với món bún riêu cua trứ danh thì riêu tôm có vẻ khá lạ với nhiều người. Tuy nhiên riêu tôm ngon không kém gì riêu cua đâu nha, và tương tự như nấu riêu cua, bạn cũng có thể làm [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/12/maxresdefault-2-1.jpg', 'https://bepxua.vn/cach-nau-lau-rieu-tom-sieu-ngon-bat-bai/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Tôm chà rửa sạch, cắt càng. Bắc nồi hấp lên bếp, cho ½ phần tôm vào hấp 15 phút. Phần tôm còn lại cắt bỏ chân râu, bỏ cục bẩn đầu tôm, lột vỏ để riêng đầu và thịt tôm."},{"step_number":2,"title":"Bước 2","description":"Cho càng tôm vào máy xay, ấn nút xay trong 30s rồi thả ra, tiếp tục ấn; cho vào 1,2l nước lọc chia 2 lần rây khuấy đều, trút ra rây lấy nước riêu. Cho vào nồi khác nước riêu tôm vừa rây hành tím, 1 muỗng cafe muối rồi nấu sôi."},{"step_number":3,"title":"Bước 3","description":"Cho thịt tôm, giò heo sống( đã để ngăn đông 1h) vào máy xay xay nhuyễn. Thêm 1 muỗng cafe hạt nêm, ½ muỗng canh nước mắm, tiêu xay, 1 muỗng canh hành phi trộn đều."},{"step_number":4,"title":"Bước 4","description":"Cà chua, hành tím xắt lát. Ngò gai, hành lá xắt nhỏ. Huyết heo xắt miếng vừa ăn."},{"step_number":5,"title":"Bước 5","description":"Cho dầu ăn vào chảo đun nóng, dầu nóng cho hành tím vào phi thơm rồi cho đầu tôm vào đảo đều 1’ sau đó cho cà chua vào, nêm 1 muỗng canh nước mắm, ½ muỗng canh đường đảo đều."},{"step_number":6,"title":"Bước 6","description":"Mở nắp nồi riêu nấu sôi, cho lần lượt nước hấp tôm, cà chua và đầu tôm đã xào, huyết heo, vo viên chả tôm thịt cho vào nấu 15’ với mức nấu nhỏ; hớt bọt cho nước trong. Nêm 1 muỗng canh hạt nêm, 1 muỗng canh mắm tôm vào nấu sôi."},{"step_number":7,"title":"Bước 7","description":"Cho bún, rau sống vào tô, chan nước lẩu lên kèm chả tôm thịt, huyết heo rồi thêm ngò gai, hành lá, nặn chanh; ăn kèm mắm tôm pha chanh ớt và thưởng thức. Tôm hấp chấm muối tiêu chanh hoặc muối ớt xanh và thưởng thức."}]'::jsonb, 44, 2.9, 0.4, 7.2, 0.7, 2613.9, 175.8, 11.7, 1.4, 28.7, 2.7, 10455.7, true),
  ('bún riêu cua đồng hải sản độc đáo tuyệt vời', 'cach-nau-bun-rieu-cua-dong-hai-san-ngon-dam-da', 'Bún riêu là một món ăn truyền thống nổi tiếng trong ẩm thực Việt. Khởi nguồn từ vùng đất Bắc bộ, bún riêu dần lan truyền và trở thành món ăn người người nhà nhà đều biết; có mặt ở các hàng quán trên khắp các nẻo đường từ làng quê lên thành thị. Không [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/11/maxresdefault-4.jpg', 'https://bepxua.vn/cach-nau-bun-rieu-cua-dong-hai-san-ngon-dam-da/', 'mon_an_sang', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cua đồng lấy gạch, bỏ yếm, chà rửa sạch rồi giã nát. Cho thịt cua vừa giã vào tô, thêm nước lọc vào bóp đều rây lấy nước cua; rây 2-3 lần với 1l nước."},{"step_number":2,"title":"Bước 2","description":"Cho vào nồi nước cua, 1 muỗng cafe muối, 2 củ hành tím nấu sôi, vớt riêu cua ra rồi tắt bếp."},{"step_number":3,"title":"Bước 3","description":"Hải sản, đậu hũ, rau rửa sạch. Mực xắt khoanh vừa ăn, huyết heo xắt miếng vừa ăn. Tôm lột vỏ, bỏ đầu và chỉ lưng. Cà chua xắt khúc. Ngò gai xắt khúc. Chanh xắt làm 2 làm 3, ớt xắt nhỏ. Hành tím còn lại cho vào máy xay gia vị xay nhuyễn."},{"step_number":4,"title":"Bước 4","description":"Cho 2 muỗng canh dầu ăn vào chảo rồi cho hạt điều đỏ vào phi lấy dầu điều sau đó cho hành tím xay vào phi thơm."},{"step_number":5,"title":"Bước 5","description":"Cho lần lượt gạch cua, cà chua, tôm, mực vào chảo rồi nêm 1 muỗng canh hạt nêm, ½ muỗng canh đường xào đều."},{"step_number":6,"title":"Bước 6","description":"Cho thêm 2l nước lọc vào nồi nước cua rồi cho tôm mực xào, 2 muỗng canh hạt nêm, 1 muỗng canh đường phèn, 1 muỗng canh nước mắm, đậu hũ, huyết heo vào, nấu 2-3 phút cho sôi. Nước sôi hớt bọt, cho 1 muỗng canh mắm tôm vào nồi rồi tắt bếp."},{"step_number":7,"title":"Bước 7","description":"Gắp bún tươi đã trụng nước sôi vào tô, thêm rau sống, riêu cua, ngò gai, ớt xắt nhỏ tùy thích rồi chan nước dùng vào; ăn kèm mắm tôm pha nước cốt chanh thêm ớt và thưởng thức."}]'::jsonb, 450.8, 86.7, 4.9, 15.1, 0.6, 5585.5, 1803.1, 346.9, 19.6, 60.3, 2.3, 22342.2, true),
  ('bún riêu cua đồng thơm ngon đậm đà', 'cach-nau-bun-rieu-cua-dong-thom-ngon-dam-da', 'Nhắc đến những món bún trứ danh trong ẩm thực Việt thì không thể nào không kể đến bún riêu. Món ăn truyền thống đậm đà hồn quê này không chỉ phổ biến trong nước mà còn được đông đảo du khách yêu thích. Từ Bắc đến Nam, bạn rất dễ tìm và nếm thử [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2022/10/bun-rieu-cua.jpg', 'https://bepxua.vn/cach-nau-bun-rieu-cua-dong-thom-ngon-dam-da/', 'mon_an_sang', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cua đồng tách mai, làm sạch, lấy gạch cua sau đó cho cua vào máy xay xay nát. Cho cua xay ra thố, thêm 1l nước lọc vào rây bỏ xác cua. Cho vào nồi nước cua hành tím, ½ muỗng cafe muối nấu sôi, vớt riêu cua nổi lên và hành tím bỏ ra."},{"step_number":2,"title":"Bước 2","description":"Cho riêu cua, thịt heo xay ra dĩa, đập thêm 3 quả trứng gà, thêm 1,5 muỗng canh hạt nêm, ½ muỗng canh đường, 1 muỗng canh nước mắm, hành phi, 1 muỗng canh dầu hành phi, tiêu xay vào trộn đều. Đem hỗn hợp vừa trộn đi hấp 20 phút."},{"step_number":3,"title":"Bước 3","description":"Cho vào chén gạch cua 1 muỗng canh dầu điều, 1 ít muối và khuấy đều sau đó đem phết lên hỗn hợp vừa hấp sau đó hấp thêm 10-15 phút là xong phần chả cua. Rắc thêm hành lá, ngò gai xắt nhỏ và tiêu xay lên để chả cua ngon hơn."},{"step_number":4,"title":"Bước 4","description":"Cho huyết heo vào nước sôi trụng sơ rồi vớt ra. Cho tiếp giò, xương, da heo vào nồi nước luộc 10 phút rồi vớt ra rửa lại nước."},{"step_number":5,"title":"Bước 5","description":"Cho 3l nước lọc vào nồi rồi cho giò, xương heo, 1 muỗng canh muối hột, hành tím vào nấu sôi. Cho ½ ống màu gạch tôm vào nồi và hầm lửa nhỏ 40 phút, nhớ vớt bọt để nước trong."},{"step_number":6,"title":"Bước 6","description":"Cho nước nấu riêu cua vào nồi nước hầm, cho tiếp cà chua đã xắt múi cau, huyết, da heo, đậu hũ viên, 3 muỗng canh đường phèn, ½ muỗng canh muối, 4 muỗng canh nước mắm, 2,5 muỗng canh mắm tôm vào nấu 10-15 phút. Tiếp theo cho 1 muỗng canh bột ngọt vào nấu sôi, vớt bọt."},{"step_number":7,"title":"Bước 7","description":"Vắt chanh vào chén mắm tôm, khuấy đều cho mắm sủi bọt rồi cho thêm ớt xay vào. Cho bún ra tô, chan nước dùng, cho thêm chả cua, hành lá, ớt xay và vắt thêm chanh vào rồi thưởng thức."}]'::jsonb, 496.9, 70.8, 13.4, 23.2, 0.9, 12580.1, 1987.4, 283.3, 53.6, 93, 3.7, 50320.4, true),
  ('bún bò Huế chay đậm vị ngon lành', 'cach-nau-bun-bo-hue-chay-dam-vi-ngon-lanh', 'Bún bò Huế trứ danh trong bản đồ ẩm thực Việt, bún bò Huế chay cũng không ngoại lệ. Hương vị thơm ngon đặc trưng của món bún đến từ cố đô luôn dễ dàng làm những người sành ăn hài lòng. Món bún bò Huế chay càng ghi điểm hơn đối với những người [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2022/09/bun-bo-hue-chay.jpg', 'https://bepxua.vn/cach-nau-bun-bo-hue-chay-dam-vi-ngon-lanh/', 'mon_chay', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Củ cải trắng, cà rốt, mướp, su su bào vỏ. Bắp lột vỏ. Nấm gọt sơ. Hành tím bóc vỏ. Rau ăn kèm lặt rồi ngâm rửa sạch hết rau củ. Sả xắt lát cho vào máy xay với hành tím xay nhuyễn."},{"step_number":2,"title":"Bước 2","description":"Củ cải trắng, cà rốt tỉa hoa, xắt lát. Mướp, bắp xắt khúc. Su su bỏ hạt xắt khúc. Thơm xắt lát. Tàu hủ ky non xắt vừa ăn. Chả quế chay xắt lát. Tàu hủ ky lá xé nhỏ cho dễ chiên. Bò lát chay ngâm mềm rồi xả lại với nước sạch, vắt xả 2-3 lần nước, vắt khô."},{"step_number":3,"title":"Bước 3","description":"Cho 3l nước lọc vào nồi rồi cho hết các củ quả đã xắt khúc vào, đậy nắp nấu sôi sau đó hạ lửa nhỏ hầm 60 phút."},{"step_number":4,"title":"Bước 4","description":"Cho 4 muỗng canh dầu ăn vào chảo đun nóng rồi cho 2 muỗng canh hạt điều đỏ DH Foods vào nấu lấy dầu màu điều, vớt bỏ hạt. Tiếp tục cho hành sả xay vào phi thơm rồi cho bò lát chay và thêm khoảng 2 muỗng canh dầu ăn vào đảo đều 1-2 phút. Cho tiếp nấm rơm vào chảo đảo đều, thêm 1 muỗng cafe đường, 1 muỗng cafe muối, 1 muỗng canh nước mắm chay vào đảo đều rồi tắt bếp."},{"step_number":5,"title":"Bước 5","description":"Cho dầu ăn vào chảo khác đun nóng rồi cho tàu hủ ky lá vào chiên giòn gắp ra. Cho tiếp chả chay và tàu hủ ky non vào chiên sơ, gắp ra."},{"step_number":6,"title":"Bước 6","description":"Cho gia vị nấu bún bò Huế DH Foods vào túi lọc, buộc chặt miệng túi. Mở nắp nồi hầm củ quả vớt củ quả ra, cho túi gia vị bún bò Huế DH Foods vào nồi nước hầm rồi cho thơm, cà rốt, củ cải trắng, 1 muỗng canh muối hột vào đậy nắp nấu sôi 20 phút."},{"step_number":7,"title":"Bước 7","description":"Sau khi sôi mở nắp nồi hầm vớt túi gia vị ra, cho nấm và bò lát chay đã xào vào đảo đều, thêm 1 muỗng canh muối hột, 2 muỗng canh nước mắm chay nêm cho nước lèo đậm vị. Nấu sôi rồi tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Cho bún vào tô, sắp chả chay, tàu hủ ky non, tàu hủ ky lá lên rồi chan nước lèo; thêm rau răm, tiêu đen xay Phú Quốc DH Foods, vắt thêm chanh, thêm rau ăn kèm, nước mắm chay sa tế theo ý thích và thưởng thức."}]'::jsonb, 147.3, 10.4, 2.8, 20.1, 2.7, 3459.8, 589.4, 41.7, 11.2, 80.6, 10.8, 13839.3, true),
  ('cơm chiên Dương Châu đậm đà ngon số dách', 'cach-lam-com-chien-duong-chau-dam-da-ngon-so-dach', 'Cơm chiên Dương Châu đến từ ẩm thực Trung Hoa, bắt nguồn nơi thành phố Dương Châu từ lâu đã được du nhập và trở thành món ăn quen thuộc với người Việt. Sự nổi bật cả về hình thức lẫn hương vị khiến món cơm chiên này trở thành món ăn yêu thích của [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/09/2XVE_Snq8No-HD.jpg', 'https://bepxua.vn/cach-lam-com-chien-duong-chau-dam-da-ngon-so-dach/', 'mon_an_sang', 'vietnamese', 4, 15, 25, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Cơm trắng để ngăn mát tủ lạnh 1 đêm. Cà rốt, đậu hà lan, hành lá rửa sạch. Cà rốt, chả lụa, lạp xưởng khô xắt hạt lựu. Hành lá xắt nhỏ."},{"step_number":2,"title":"Bước 2","description":"Trước khi chiên 30 phút lấy cơm ra ngoài cho hết lạnh, sau đó đập trứng vào cơm, thêm ⅔ muỗng canh hạt nêm, 1 muỗng canh dầu màu điều rồi trộn đều, bóp cho cơm tơi ra."},{"step_number":3,"title":"Bước 3","description":"Nấu sôi 500ml nước, nước sôi cho cà rốt, đậu hà lan vào luộc 4 phút rồi vớt ra."},{"step_number":4,"title":"Bước 4","description":"Làm nóng chảo rồi cho lạp xưởng vào đảo đều lạp xưởng đến khi ra mỡ thì cho chả lụa, cà rốt, đậu hà lan, 2 muỗng canh nước tương và đảo đều khoảng 2 phút rồi cho ra tô."},{"step_number":5,"title":"Bước 5","description":"Tỏi cho vào máy xay gia vị xay nhuyễn. Cho 2 muỗng canh dầu ăn vào chảo đun nóng, dầu nóng cho tỏi xay vào phi thơm rồi cho cơm vào đảo lửa vừa đến khi cơm khô, tơi ra, nổ lách tách thì cho hỗn hợp  lạp xưởng, chả lụa, cà rốt, đậu hà lan và 1 muỗng cafe đường hoặc ½ muỗng cafe bột ngọt vào đảo đều, rắc thêm hành lá rồi tắt bếp."},{"step_number":6,"title":"Bước 6","description":"Cho cơm chiên Dương Châu ra dĩa, ăn kèm cà chua, dưa leo, trứng ốp la, tiêu xay, tương ớt tùy ý… và thưởng thức."}]'::jsonb, 791.2, 21.8, 23.5, 123, 1.6, 3516.1, 3164.8, 87.3, 94.2, 492, 6.5, 14064.5, true),
  ('lẩu gà lá giang thơm ngon bổ dưỡng trứ danh', 'cach-nau-lau-ga-la-giang-thom-ngon-bo-duong-tru-danh', 'Lẩu gà lá giang là một trong những món lẩu nằm top phổ biến nhất và rất được các tín đồ sành ăn yêu thích khi nhắc đến những món lẩu gà. Thịt gà mềm ngọt và lá giang chát chua tưởng không hợp mà lại hợp không tưởng, sự kết hợp này đã đem [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2024/07/maxresdefault-4.jpg', 'https://bepxua.vn/cach-nau-lau-ga-la-giang-thom-ngon-bo-duong-tru-danh/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Dùng muối thoa đều gà, cắt bỏ móng rồi rửa sạch. Tiếp tục dùng chanh thoa gà khử mùi rồi rửa sạch, chặt miếng vừa ăn và rửa sạch lại lần nữa. Lá giang lặt lá, ngâm rửa sạch với nước muối, vò sơ. Rau ăn kèm làm rửa sạch, ngò om ngò gai ớt xắt nhỏ."},{"step_number":2,"title":"Bước 2","description":"Cho gừng xắt lát và 1 muỗng canh nước mắm vào nồi 2l nước rồi nấu sôi, nước sôi cho gà vào trụng sơ 2 phút để khi nấu nước dùng sẽ trong, không bị tanh. Sau khi trụng vớt gà ra."},{"step_number":3,"title":"Bước 3","description":"Tỏi, hành tím cho vào máy xay gia vị xay nhuyễn. Cho gà ra tô, cho ½ phần hành tỏi xay, 1 muỗng cafe muối, 1 muỗng cafe hạt nêm, 1 muỗng canh đường phèn, 2 muỗng canh nước mắm, 1-2 muỗng canh sa tế, tiêu xay vào tô trộn đều gà, ướp 15 phút."},{"step_number":4,"title":"Bước 4","description":"Cho 3 muỗng canh dầu ăn vào nồi và đun nóng, dầu nóng cho sả đập dập và phần hành tỏi xay còn lại vào phi thơm rồi cho thịt gà vào đảo đều khoảng 5 phút."},{"step_number":5,"title":"Bước 5","description":"Cho 2,5l nước lọc vào nồi đậy nắp nấu sôi với lửa lớn, nước sôi mở nắp hớt bọt, nấu tiếp 15-20 phút với lửa nhỏ vừa."},{"step_number":6,"title":"Bước 6","description":"Cho 1 muỗng canh dầu ăn vào chảo và đun nóng, dầu nóng cho lá giang vào xào sơ 1 phút để khi nấu nước dùng không bị chát."},{"step_number":7,"title":"Bước 7","description":"Cho từ từ lá giang vào nồi lẩu, gia giảm tùy độ chua và khẩu vị, nêm 1 muỗng cafe muối, 1 muỗng canh đường phèn, ½ muỗng cafe bột ngọt, 2 muỗng canh nước mắm đảo đều."},{"step_number":8,"title":"Bước 8","description":"Cho 1 muỗng canh muối hột, ½ muỗng canh đường phèn, ½ muỗng cafe bột ngọt, ớt tùy thích vào cối rồi giã nát, vắt thêm nước cốt chanh vào khuấy đều làm muối chấm."},{"step_number":9,"title":"Bước 9","description":"Cho vào nồi lẩu ngò om, ngò gai, ớt, nấm, rau muống, chuối cây, bắp chuối vừa nấu vừa ăn. Múc bún vào chén, chan nước lẩu, chấm thịt gà với muối chấm và thưởng thức."}]'::jsonb, 95.8, 2.9, 1.4, 18, 0.6, 3402.8, 383, 11.6, 5.5, 71.8, 2.3, 13611.3, true),
  ('lẩu bò Mông Cổ thơm ngon đơn giản tại nhà', 'cach-nau-lau-bo-mong-co-thom-ngon-don-gian-tai-nha', 'Trong thời gian gần đây, lẩu bò Mông Cổ nổi lên như một hiện tượng đối với những tín đồ yêu ẩm thực. Món ăn bắt nguồn từ ẩm thực Trung Hoa này nhanh chóng chiếm được cảm tình của hội sành ăn. Với sức hút như vậy, không khó hiểu khi lẩu bò Mông [&hellip;]', 'https://bepxua.vn/wp-content/uploads/2023/12/maxresdefault-7.jpg', 'https://bepxua.vn/cach-nau-lau-bo-mong-co-thom-ngon-don-gian-tai-nha/', 'mon_man', 'vietnamese', 4, 15, 30, 'medium', '[{"step_number":1,"title":"Bước 1","description":"Nguyên liệu sơ chế rửa sạch. Bắp bò, thịt bò, rìa thăn bò xắt lát mỏng."},{"step_number":2,"title":"Bước 2","description":"Cho rìa thăn bò, 20 gram gừng và hành baro xắt nhỏ, ½ muỗng canh đường, ½ muỗng canh hạt nêm, 1 muỗng canh dầu hào, tiêu xay vào máy xay xay nhuyễn vừa."},{"step_number":3,"title":"Bước 3","description":"Cho thịt xay vào bao tử dê cuộn tròn lại ,dùng dây chỉ buộc chặt. Làm tương tự cho đến khi chỉ còn phần rìa thì xắt phần rìa thành từng miếng vừa ăn."},{"step_number":4,"title":"Bước 4","description":"Cho vào nồi sả, 20 gram gừng xắt lát và 50ml rượu rồi đun sôi sau đó cho bao tử nhồi thịt và phần rìa bao tử vào luộc 2-3 phút xong vớt ra."},{"step_number":5,"title":"Bước 5","description":"Lấy 30 gram gừng xắt lát và hành tây cho lên vỉ nướng nướng sơ."},{"step_number":6,"title":"Bước 6","description":"Cho vào nồi khác 2,5l nước dừa tươi hoặc nước hầm xương, bao tử nhồi thịt đã luộc, hành tây và gừng vừa nướng, quế cây, hoa hồi, táo đỏ, đông trùng, ớt (tùy khẩu vị), 1 muỗng canh muối hạt, 1 muỗng canh đường phèn đậy nắp nấu sôi, vớt bọt cho nước trong. Hầm lẩu 60 phút với lửa nhỏ vừa."},{"step_number":7,"title":"Bước 7","description":"Sau 60 phút mở nắp nồi nước lẩu đảo đều, thêm nấm hương, 1,5 muỗng canh hạt nêm nấu sôi lại tắt bếp."},{"step_number":8,"title":"Bước 8","description":"Hoa hẹ, táo bơm xắt khúc. Cho ⅔ hoa hẹ, táo bơm, ½ muỗng cafe muối, 30ml nước lọc vào máy xay xay nhuyễn cho ra chén làm nước chấm hoa hẹ."},{"step_number":9,"title":"Bước 9","description":"Cho vào chén 2 muỗng canh chao, 1 muỗng canh sa tế, ½ muỗng canh đường khuấy đều làm nước chấm chao sa tế."},{"step_number":10,"title":"Bước 10","description":"Múc nước lẩu ra thố nhỏ, bẻ mì gói hoặc mì trứng cho vào, thêm cải, nấm linh chi, bao tử nhồi thịt, bắp bò, rau tần ô nấu sôi lại, chấm nước chấm chao sa tế; dùng dao xẻ đôi bao tử nhồi thịt, chấm nước chấm hoa hẹ và thưởng thức."}]'::jsonb, 292.3, 30.7, 5.2, 22.2, 2.8, 7662.1, 1169.1, 122.8, 21, 88.9, 11.1, 30648.3, true)
